func numIslands(_ grid: [[Character]]) -> Int {
    guard !grid.isEmpty, !grid[0].isEmpty else { return 0 }
    var mat = grid
    let rows = mat.count
    let cols = mat[0].count
    var count = 0
    let dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    func dfs(_ r: Int, _ c: Int) {
        guard r >= 0, r < rows, c >= 0, c < cols, mat[r][c] == "1" else { return }
        mat[r][c] = "0"
        for (dr, dc) in dirs { dfs(r + dr, c + dc) }
    }
    for r in 0..<rows {
        for c in 0..<cols {
            if mat[r][c] == "1" {
                count += 1
                dfs(r, c)
            }
        }
    }
    return count
}
let grid: [[Character]] = [["1", "0"], ["0", "1"]]
print(numIslands(grid))

