func floodFill(_ image: inout [[Int]], _ sr: Int, _ sc: Int, _ newColor: Int) {
    let rows = image.count
    guard rows > 0 else { return }
    let cols = image[0].count
    let startColor = image[sr][sc]
    guard startColor != newColor else { return }
    let dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    func dfs(_ r: Int, _ c: Int) {
        guard r >= 0, r < rows, c >= 0, c < cols, image[r][c] == startColor else { return }
        image[r][c] = newColor
        for (dr, dc) in dirs { dfs(r + dr, c + dc) }
    }
    dfs(sr, sc)
}

var img = [[1, 1, 1], [1, 1, 0], [1, 0, 1]]
floodFill(&img, 1, 1, 2)
print(img)

func rotateSquareMatrix(_ matrix: inout [[Int]]) {
    let n = matrix.count
    guard n > 1 else { return }
    for r in 0..<n {
        for c in (r + 1)..<n {
            let tmp = matrix[r][c]
            matrix[r][c] = matrix[c][r]
            matrix[c][r] = tmp
        }
    }
    for r in 0..<n {
        matrix[r].reverse()
    }
}

var grid = [[1, 2], [3, 4]]
rotateSquareMatrix(&grid)
print(grid)

func diagonalSum(_ mat: [[Int]]) -> Int {
    let n = mat.count
    var sum = 0
    for i in 0..<n {
        sum += mat[i][i]
        sum += mat[i][n - 1 - i]
    }
    if n % 2 == 1 {
        sum -= mat[n / 2][n / 2]
    }
    return sum
}

let m = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
print(diagonalSum(m))
